export type Mode = "host" | "process" | "all";

export type MonitorEvent = 
/**
 *  Capture is open and packets are being counted. Also sent to a new
 *  subscriber while a session runs, so a reloaded window catches up.
 */
({ kind: "started"; session: SessionInfo }) & { message?: never; reason?: never; recording?: never; sessionId?: never } | 
/**  One measurement tick. */
{
	kind: "sample",
} & Sample | 
/**  Capture ended (user or agent request, or an error). */
({ kind: "stopped"; sessionId: number; reason: StopReason; message: string | null }) & { recording?: never; session?: never } | 
/**  A recording started (from the window or an agent). */
({ kind: "recordingStarted"; sessionId: number; recording: RecordingInfo }) & { message?: never; reason?: never; session?: never } | 
/**  The recording ended (stopped, or the session ended); it is complete on disk. */
({ kind: "recordingStopped"; sessionId: number; recording: RecordingInfo }) & { message?: never; reason?: never; session?: never } | 
/**  A non-fatal problem (e.g. one of several interfaces failed). */
({ kind: "warning"; sessionId: number; message: string }) & { reason?: never; recording?: never; session?: never };

export type NameSource = 
/**  TLS server name of a connection to this address. */
"sni" | 
/**  A DNS (or mDNS) answer that returned this address. */
"dns" | 
/**
 *  The outer server name of an Encrypted Client Hello: a shared front
 *  (e.g. `cloudflare-ech.com`), not the real site.
 */
"echOuter" | 
/**  PTR record. */
"reverseDns";

export type NamingInfo = {
	/**  Interfaces with a naming capture running. */
	sniffers: number,
	reverseDns: boolean,
};

export type NamingOptions = {
	/**  Read DNS answers and TLS server names from the wire. */
	sniff?: boolean,
	/**  Look up PTR records for unnamed endpoints (queries your DNS server). */
	reverseDns?: boolean,
};

export type Neighbor = {
	ip: string,
	/**  "aa:bb:cc:dd:ee:ff" */
	mac: string,
	/**  "reachable" | "stale" | "delay" | "probe" | "permanent" */
	state: string,
	interfaceIndex: number,
};

export type NetContext = {
	gateways: Gateway[],
	neighbors: Neighbor[],
};

/**  A device first seen in the latest scan of a network already known. */
export type NewDevice = {
	mac: string,
	ip: string,
	vendor: string | null,
	hostname: string | null,
};

/**  Result of probing for the Npcap runtime, shared with the UI. */
export type NpcapStatus = {
	/**  `true` when pcap functions can safely be called. */
	available: boolean,
	/**  Folder the Npcap DLLs were loaded from (Windows). */
	dllDir: string | null,
	/**  Version string reported by `pcap_lib_version()`. */
	version: string | null,
	/**  Human-readable explanation when unavailable. */
	message: string | null,
	/**
	 *  Linux, when capturing is not permitted: the command that grants this
	 *  executable the permission. `None` when no command can (the file sits
	 *  where capabilities do not apply).
	 */
	grantCommand: string | null,
};

/**  A server a program offered an outdated TLS version to. */
export type OldTls = {
	server: EndpointRef,
	/**  "TLS 1.0" */
	version: string,
};

/**  One open port on a device, with the service it usually means. */
export type OpenPort = {
	port: number,
	service: string | null,
};

/**  Owner and country of an address. */
export type Owner = {
	asn: number | null,
	/**  Network owner, e.g. "Cloudflare, Inc.". */
	org: string | null,
	/**  ISO 3166-1 alpha-2, e.g. "US". */
	country: string | null,
	source: OwnerSource,
};

export type OwnerSource = 
/**  DB-IP Lite database on this machine. */
"dbip" | 
/**  ipinfo.io online lookup. */
"ipinfo";

export type PacketBatch = {
	rows: PacketRow[],
	/**  Sequence number the next packet will get. */
	nextSeq: number,
	enabled: boolean,
};

/**  A packet as sent to the UI. */
export type PacketRow = {
	seq: number,
	tsUs: number,
	iface: number,
	/**  `"in"` (received by the monitored side) or `"out"`. */
	dir: Direction,
	src: string,
	dst: string,
	transport: Transport,
	srcPort: number | null,
	dstPort: number | null,
	len: number,
	ttl: number,
	pid: number | null,
	/**  Program name (all-traffic mode). */
	program: string | null,
	/**  Best known name of the remote side. */
	remoteName: string | null,
};

/**  One ping target as sent to the UI. */
export type PingStatus = {
	ip: string,
	running: boolean,
	startedAtMs: number,
	sent: number,
	received: number,
	/**  Lost share of the last 60 probes. */
	lossPct: number | null,
	lastMs: number | null,
	/**  Mean of the replies among the last 60 probes. */
	avgMs: number | null,
	minMs: number | null,
	maxMs: number | null,
	/**  RFC 3550-style jitter: smoothed difference between consecutive replies. */
	jitterMs: number | null,
	/**  Last 120 probes, oldest first; `null` = lost. */
	history: (number | null)[],
	/**  Why probing stopped early (ICMP API failure). */
	error: string | null,
};

/**  A program's use of one unencrypted service. */
export type PlainUse = {
	/**  "HTTP", "Telnet", … */
	service: string,
	transport: Transport,
	port: number,
	certainty: Certainty,
	bytes: number,
	/**
	 *  Bytes exchanged with addresses on the Internet (the rest stayed on
	 *  the local network).
	 */
	publicBytes: number,
	endpointCount: number,
	/**  The busiest few. */
	endpoints: EndpointRef[],
};

/**
 *  The system Fishe runs on, for the wording that differs (how capture is
 *  allowed, what the file manager is called).
 */
export type Platform = "windows" | "linux" | "other";

/**  Cumulative usage of one service port. */
export type PortUsage = {
	transport: Transport,
	port: number,
	bytes: number,
	packets: number,
};

/**
 *  All processes sharing an executable name. This is what the picker shows,
 *  and what "bind by name" follows.
 */
export type ProcessGroup = {
	name: string,
	pids: number[],
	/**  Full image path of one instance, when readable. */
	exePath: string | null,
	/**  All TCP/UDP sockets owned by the group. */
	sockets: number,
	/**  TCP connections with a remote peer. */
	connections: number,
	listening: number,
};

export type ProcessSelector = 
/**
 *  Every process with this executable name (case-insensitive), including
 *  ones started after monitoring began.
 */
{ by: "name"; name: string } | 
/**  Exactly one process. */
{ by: "pid"; pid: number };

export type ProcessSessionInfo = {
	selector: ProcessSelector,
	/**  PIDs matched when the session started. */
	pids: number[],
	exePath: string | null,
};

export type ProcessTick = {
	/**  Currently matched PIDs (at most 64 listed). */
	pids: number[],
	pidCount: number,
	/**  Sockets owned by the matched PIDs at the last socket-table poll. */
	sockets: number,
	/**  Port→PID mappings currently known (all processes). */
	knownPorts: number,
};

/**  One program's side of the session. */
export type ProgramAudit = {
	/**  Grouping key (lower-case executable name; `""` = unattributed). */
	key: string,
	name: string,
	bytes: number,
	/**  Remote addresses it exchanged traffic with. */
	endpoints: number,
	/**  Those on the Internet. */
	publicEndpoints: number,
	/**  Countries of the public endpoints, most traffic first. */
	countries: Share[],
	/**  Organisations owning them, most traffic first (a few). */
	owners: Share[],
	ownerCount: number,
	/**
	 *  Public endpoints whose owner is not known (no owner database, or
	 *  not in it).
	 */
	unknownOwner: number,
	plaintext: PlainUse[],
	/**  Bytes over services that are certainly unencrypted. */
	plainBytes: number,
	tlsHellos: number,
	oldTls: OldTls[],
};

/**  One program as sent to the UI. */
export type ProgramRow = {
	key: string,
	name: string,
	/**  PIDs seen sending/receiving (at most 16 listed). */
	pids: number[],
	inBps: number,
	outBps: number,
	smoothedBps: number,
	baselineBps: number,
	ratio: number,
	level: Level,
	peakBps: number,
	totals: Counters,
	/**  Distinct remote addresses this session. */
	endpoints: number,
	firstSeenMs: number,
	lastSeenMs: number,
};

export type ProgramsTick = {
	/**  Programs seen this session (rows may hold a subset). */
	total: number,
	rows: ProgramRow[],
};

/**  Session quality in each sample. */
export type QualityTick = {
	/**  Mean RTT of the samples in the last 10 s. */
	rttMs: number | null,
	/**  Mean RTT of this tick's samples (for the chart). */
	rttTickMs: number | null,
	/**  Lowest RTT this session. */
	minRttMs: number | null,
	/**
	 *  Smoothed RTT and jitter over all samples in order. Meaningful when
	 *  they come from one endpoint (host mode, or one dominant peer).
	 */
	srttMs: number | null,
	jitterMs: number | null,
	/**  RTT samples in the last 10 s. */
	recentSamples: number,
	/**  Retransmitted share of TCP payload in the last 10 s, sent / received. */
	retransOutPct: number | null,
	retransInPct: number | null,
	/**  Session totals (TCP payload bytes). */
	dataOut: number,
	dataIn: number,
	retransOut: number,
	retransIn: number,
	rttSamples: number,
};

/**  Who can reach a listening socket. */
export type Reach = 
/**
 *  Bound to a network address: other machines can connect, unless a
 *  firewall stops them (which Fishe does not see).
 */
"network" | 
/**  Bound to the loopback address: this machine only. */
"loopback";

export type RecordOptions = {
	/**  Display name; defaults to the session label. */
	name?: string | null,
	/**  Also save the counted packets' headers to a .pcapng file. */
	pcap?: boolean,
};

export type RecordingDetail = {
	summary: RecordingSummary,
	/**
	 *  The session the recording was made in; `None` if its stored JSON
	 *  no longer parses (a recording from an incompatible version).
	 */
	session: SessionInfo | null,
	/**  End-of-recording extras; `None` while recording or when interrupted. */
	extra: RecordingExtra | null,
	samples: SeriesPoint[],
	/**  Samples were averaged into fewer points for display. */
	downsampled: boolean,
	endpoints: EndpointRecord[],
	episodes: Episode[],
};

/**  Whole-recording figures written when a recording ends (`summary_json`). */
export type RecordingExtra = {
	transports: TransportBytes,
	topPorts: PortUsage[],
	dropped: number,
	ifDropped: number,
	unattributed: number,
	/**  TCP quality over the recording (recordings since 0.8). */
	quality?: EndpointQuality | null,
	/**  All-traffic recordings: the programs that moved the most bytes (≤ 25). */
	programs?: RecordingProgram[] | null,
};

export type RecordingInfo = {
	id: number,
	name: string,
	/**  Unix ms. */
	startedAt: number,
	pcapPath: string | null,
};

/**  One program's share of an all-traffic recording. */
export type RecordingProgram = {
	key: string,
	name: string,
	bytesIn: number,
	bytesOut: number,
	endpoints: number,
	peakBps: number,
};

export type RecordingStatus = "recording" | "complete" | "interrupted";

export type RecordingSummary = {
	id: number,
	name: string,
	mode: Mode,
	label: string,
	startedAt: number,
	endedAt: number | null,
	durationMs: number,
	status: RecordingStatus,
	sampleCount: number,
	totals: Counters,
	peakBps: number,
	maxLevel: Level,
	endpointCount: number,
	pcapPath: string | null,
	pcapPackets: number,
	pcapDropped: number,
	pcapBytes: number | null,
};

/**  Live recording status, included in every sample while recording. */
export type RecordingTick = {
	id: number,
	elapsedMs: number,
	samples: number,
	pcapPackets: number,
	pcapDropped: number,
};

export type ResolvedTarget = {
	/**  The trimmed user input. */
	input: string,
	/**  The address that will be monitored. */
	ip: string,
	/**  `true` when `input` was a host name and DNS was used. */
	fromHostname: boolean,
	/**  Every address DNS returned (the first IPv4 one is preferred). */
	candidates: string[],
};

export type Route = {
	via: RouteVia,
	/**  Description of the interface used. */
	interface: string | null,
};

/**  How Internet-bound traffic of one address family leaves this machine. */
export type RouteVia = 
/**  Through a tunnel interface. */
"tunnel" | 
/**  Through an ordinary adapter. */
"direct" | 
/**  This machine has no route for that family. */
"none";

/**  A measurement over the last tick. Rates are bytes (or packets) per second. */
export type Sample = {
	sessionId: number,
	/**  Milliseconds since the capture started. */
	tMs: number,
	/**  Real duration of this tick in milliseconds. */
	intervalMs: number,
	inBps: number,
	outBps: number,
	inPps: number,
	outPps: number,
	/**  Busyness detector output (see `gauge.rs`). */
	smoothedBps: number,
	baselineBps: number,
	ratio: number,
	level: Level,
	/**  Highest `in_bps + out_bps` seen so far. */
	peakBps: number,
	totals: Counters,
	transports: TransportBytes,
	topPorts: PortUsage[],
	/**  Packets the OS buffers dropped (we were too slow) since start, all interfaces. */
	dropped: number,
	/**  Packets the interfaces/drivers dropped since start. */
	ifDropped: number,
	/**
	 *  Packets that could not be attributed to any process (process mode:
	 *  dropped from the counts; all-traffic mode: counted as *Unattributed*).
	 */
	unattributed: number,
	/**
	 *  Live process information (process mode), or socket-table figures for
	 *  the whole machine (all-traffic mode: `pids` empty, `pid_count` = PIDs
	 *  owning sockets).
	 */
	process: ProcessTick | null,
	/**  Remote endpoints (process and all-traffic modes). */
	endpoints: EndpointsTick | null,
	/**  Programs using the network (all-traffic mode only). */
	programs: ProgramsTick | null,
	/**  TCP connection quality of the counted traffic (RTT, retransmissions). */
	quality: QualityTick | null,
	/**  Live recording status, while recording. */
	recording: RecordingTick | null,
};

/**  Everything the Security page shows. */
export type SecurityReport = {
	state: SessionState,
	session: SessionAudit | null,
	/**  Programs accepting TCP connections right now; reachable ones first. */
	listeners: Listener[],
	/**  Why `listeners` is empty, when the socket table could not be read. */
	listenersError: string | null,
	/**  Local networks scanned so far, latest first. */
	lans: KnownLan[],
	/**
	 *  Tunnel interfaces, where Internet traffic leaves, and what left
	 *  outside the tunnel.
	 */
	vpn: VpnAudit,
	/**
	 *  Is the owner database installed? Without it organisations and
	 *  countries are unknown.
	 */
	ownerData: boolean,
	/**  Most severe first. */
	findings: Finding[],
};

export type SeriesPoint = {
	tMs: number,
	inBps: number,
	outBps: number,
	smoothedBps: number,
	baselineBps: number,
	ratio: number,
	level: Level,
	/**  Mean TCP round-trip time of the tick (recordings since schema v3). */
	rttMs?: number | null,
};

/**  What an all-traffic session saw. */
export type SessionAudit = {
	/**  Session time covered. */
	tMs: number,
	/**  Busiest first. */
	programs: ProgramAudit[],
	programCount: number,
	/**  Most ports tried first. */
	inbound: InboundPeer[],
	inboundCount: number,
	dns: DnsAudit,
	/**  DHCP servers seen answering during the session, by interface. */
	dhcp: DhcpSeen[],
};

/**
 *  What the window would send with a start: its Settings (sensitivity,
 *  reverse DNS). Kept here so a session an agent starts measures the same
 *  way as one started with the button.
 */
export type SessionDefaults = {
	gauge?: GaugeOverrides | null,
	naming?: NamingOptions,
};

/**  Describes the running session. */
export type SessionInfo = {
	sessionId: number,
	mode: Mode,
	/**  Short display name: an IP, `chrome.exe` or `PID 1234`. */
	label: string,
	/**  Host mode: the monitored address. */
	target: string | null,
	/**  Host mode: the host name it was resolved from, if any. */
	resolvedFrom: string | null,
	process: ProcessSessionInfo | null,
	attribution: Attribution | null,
	/**  Endpoint naming (process and all-traffic modes). */
	naming: NamingInfo | null,
	interfaces: CaptureInterface[],
	filter: string,
	tickMs: number,
	gauge: GaugeConfig,
};

/**  Why the report has no session part. */
export type SessionState = 
/**  An all-traffic session is running: `session` is filled. */
"auditing" | 
/**  Nothing is being monitored. */
"noSession" | 
/**
 *  A session runs, but on one host or one program: it does not see
 *  the whole machine.
 */
"notAllTraffic";

/**  How much attention a finding asks for. */
export type Severity = 
/**  Worth knowing; usually nothing to do. */
"info" | 
/**  Worth a look. */
"notice" | 
/**  Worth acting on, or at least understanding. */
"warning";

export type Share = {
	/**  A country code ("US") or an organisation's name. */
	name: string,
	bytes: number,
	endpoints: number,
};

/**
 *  Parameters for [`MonitorState::start`], sent by the UI (or built from an
 *  agent's `start_monitoring` call plus the window's [`SessionDefaults`]).
 */
export type StartRequest = {
	target: TargetSpec,
	/**
	 *  Capture device name. `None`: host mode picks the route's interface,
	 *  process mode captures on every active interface.
	 */
	interface?: string | null,
	/**  Detector tuning; missing fields use defaults. */
	gauge?: GaugeOverrides | null,
	/**  Sample period in milliseconds (clamped to 50..=2000, default 250). */
	tickMs?: number | null,
	/**  Endpoint naming (process mode); missing fields use defaults. */
	naming?: NamingOptions,
};

export type StopReason = "userRequested" | "error";

/**  The target requested by the UI. */
export type TargetSpec = 
/**  All traffic between this machine and one remote address. */
{ kind: "host"; address: string } | 
/**  All traffic of one program (or one PID), to any address. */
{ kind: "process"; selector: ProcessSelector } | 
/**  Every packet of this machine, labelled with its program. */
{ kind: "all" };

export type TraceResult = {
	target: string,
	/**  Unix ms. */
	startedAt: number,
	durationMs: number,
	/**  The destination answered. */
	reached: boolean,
	hops: Hop[],
};

/**  Transport-layer protocol of a packet. */
export type Transport = "tcp" | "udp" | 
/**  ICMP (IPv4) or ICMPv6. */
"icmp" | "other";

/**  Bytes per transport protocol. */
export type TransportBytes = {
	tcp: number,
	udp: number,
	icmp: number,
	other: number,
};

/**  A tunnel interface that is up. */
export type Tunnel = {
	/**  Capture device name. */
	name: string,
	description: string,
	/**  "WireGuard", "OpenVPN", … */
	kind: string,
	addresses: string[],
};

/**  The VPN card. */
export type VpnAudit = {
	/**  Tunnel interfaces that are up. */
	tunnels: Tunnel[],
	ipv4: Route,
	ipv6: Route,
	/**  Why the interfaces could not be listed, when they could not. */
	error: string | null,
	/**
	 *  The running all-traffic session captures on a tunnel, so the figures
	 *  below mean something. Otherwise they are zero.
	 */
	measured: boolean,
	/**  Bytes exchanged with Internet addresses inside the tunnel. */
	insideBytes: number,
	/**
	 *  Bytes exchanged with Internet addresses outside it, the VPN server's
	 *  own traffic included.
	 */
	outsideBytes: number,
	/**
	 *  The busiest address reached outside the tunnel: almost always the
	 *  VPN server, which the tunnel's own packets travel to.
	 */
	carrier: EndpointRef | null,
	/**  The other Internet addresses reached outside the tunnel (a few). */
	outside: EndpointRef[],
	/**  How many there are. */
	outsideCount: number,
	/**  Unencrypted DNS questions that left outside the tunnel. */
	dnsOutside: number,
};

